INSERT INTO recipe (id, title, ingredients_raw, instructions_raw, source_type, review_count, wish_count, avg_score, source_ref, version) VALUES
(10051, '강원도식 제육볶음', '양파 1개, 브로콜리 1개, 당근 1/2개, 계란 2개', '1. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n2. 약불에서 30분간 푹 끓인다\n3. 팬에 기름을 두르고 센 불에 달군다\n4. 소금으로 간을 맞춘다\n5. 밥과 함께 담아낸다', 'EXTERNAL_API', 28, 19, 4.1, 'RCP_10051', 0),
(10052, '강원도식 오징어볶음', '깨소금 1작은술, 다진마늘 1큰술, 밀가루 1컵, 대파 1대, 부추 100g, 느타리버섯 100g', '1. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 양념을 만들어 재료에 버무린다\n4. 냄비에 육수를 넣고 끓인다\n5. 두부를 넣고 5분 더 끓인다', 'EXTERNAL_API', 28, 26, 2.0, 'RCP_10052', 0),
(10053, '강원도식 낙지볶음', '김치 300g, 새우 200g, 콩나물 200g, 오징어 1마리, 대파 1대, 어묵 200g', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 양념장을 넣고 골고루 섞는다\n3. 물을 붓고 끓기 시작하면 중불로 줄인다\n4. 밥과 함께 담아낸다\n5. 재료를 깨끗이 씻어 준비한다', 'EXTERNAL_API', 25, 29, 1.8, 'RCP_10053', 0),
(10054, '강원도식 쭈꾸미볶음', '식용유 2큰술, 김치 300g, 계란 2개, 고추장 2큰술, 멸치 육수 500ml', '1. 그릇에 담아 깨소금을 뿌린다\n2. 양념장을 넣고 골고루 섞는다\n3. 약불에서 30분간 푹 끓인다\n4. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 17, 1, 3.4, 'RCP_10054', 0),
(10055, '강원도식 김치볶음', '생강 1쪽, 물 500ml, 배추 300g, 간장 3큰술, 고추 2개, 김치 300g, 콩나물 200g', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 약불에서 30분간 푹 끓인다\n4. 접시에 보기 좋게 담아낸다\n5. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 47, 15, 3.2, 'RCP_10055', 0),
(10056, '강원도식 멸치볶음', '소금 약간, 계란 2개, 당면 200g, 파프리카 1개, 고추 2개, 생강 1쪽, 소고기 300g, 브로콜리 1개', '1. 양념장을 넣고 골고루 섞는다\n2. 야채를 적당한 크기로 썰어 준비한다\n3. 뚜껑을 덮고 15분간 끓인다', 'EXTERNAL_API', 10, 2, 2.8, 'RCP_10056', 0),
(10057, '강원도식 어묵볶음', '후추 약간, 떡 300g, 부추 100g, 소고기 300g, 돼지고기 200g, 맛술 1큰술', '1. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 대파를 넣고 한소끔 끓인다\n4. 그릇에 담아 깨소금을 뿌린다\n5. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 41, 5, 1.1, 'RCP_10057', 0),
(10058, '강원도식 감자볶음', '삼겹살 300g, 무 200g, 콩나물 200g, 닭고기 400g, 소고기 300g, 깻잎 10장', '1. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n2. 밥과 함께 담아낸다\n3. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 18, 30, 4.9, 'RCP_10058', 0),
(10059, '강원도식 버섯볶음', '쌈장 2큰술, 식용유 2큰술, 브로콜리 1개, 멸치 육수 500ml, 새우 200g, 설탕 1큰술, 고구마 2개', '1. 그릇에 담아 깨소금을 뿌린다\n2. 양념장을 넣고 골고루 섞는다\n3. 참기름을 두르고 불을 끈다\n4. 두부를 넣고 5분 더 끓인다\n5. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 10, 23, 4.3, 'RCP_10059', 0),
(10060, '강원도식 소시지볶음', '굴소스 1큰술, 고춧가루 1큰술, 설탕 1큰술, 계란 2개, 밀가루 1컵', '1. 재료를 깨끗이 씻어 준비한다\n2. 소금으로 간을 맞춘다\n3. 물을 붓고 끓기 시작하면 중불로 줄인다\n4. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 22, 17, 4.2, 'RCP_10060', 0),
(10061, '강원도식 두부볶음', '고추장 2큰술, 참기름 1큰술, 삼겹살 300g, 마늘 5쪽, 물 500ml, 가지 2개, 다진마늘 1큰술', '1. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 30, 20, 3.9, 'RCP_10061', 0),
(10062, '강원도식 고추장볶음', '참기름 1큰술, 마늘 5쪽, 오징어 1마리, 표고버섯 4개, 삼겹살 300g, 고춧가루 1큰술, 소금 약간', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 야채를 적당한 크기로 썰어 준비한다\n3. 대파를 넣고 한소끔 끓인다\n4. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 44, 15, 1.4, 'RCP_10062', 0),
(10063, '강원도식 된장볶음', '콩나물 200g, 돼지고기 200g, 김치 300g, 배즙 3큰술, 고추 2개, 호박 1/2개, 표고버섯 4개', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 밥과 함께 담아낸다\n3. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n4. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 15, 29, 5.0, 'RCP_10063', 0),
