INSERT INTO recipe (id, title, ingredients_raw, instructions_raw, source_type, review_count, wish_count, avg_score, source_ref, version) VALUES
(11751, '광주식 삼계탕', '깨소금 1작은술, 식용유 2큰술, 새송이버섯 2개, 호박 1/2개, 파프리카 1개, 당면 200g, 굴소스 1큰술', '1. 두부를 넣고 5분 더 끓인다\n2. 냄비에 육수를 넣고 끓인다\n3. 재료를 깨끗이 씻어 준비한다\n4. 소금으로 간을 맞춘다\n5. 대파를 넣고 한소끔 끓인다', 'EXTERNAL_API', 15, 21, 3.1, 'RCP_11751', 0),
(11752, '광주식 감자탕', '양파 1개, 양배추 200g, 버섯 100g, 생강 1쪽, 호박 1/2개, 콩나물 200g', '1. 양념장을 넣고 골고루 섞는다\n2. 양념을 만들어 재료에 버무린다\n3. 야채를 적당한 크기로 썰어 준비한다\n4. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 35, 28, 3.9, 'RCP_11752', 0),
(11753, '광주식 뼈해장국', '연근 200g, 돼지고기 200g, 팽이버섯 100g, 양파 1개, 계란 2개, 새송이버섯 2개, 배즙 3큰술, 물 500ml', '1. 야채를 데쳐서 찬물에 헹군다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 재료를 깨끗이 씻어 준비한다\n4. 대파를 넣고 한소끔 끓인다', 'EXTERNAL_API', 39, 10, 4.4, 'RCP_11753', 0),
(11754, '광주식 선지해장국', '대파 1대, 팽이버섯 100g, 깨소금 1작은술, 식용유 2큰술, 김치 300g', '1. 대파를 넣고 한소끔 끓인다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 밥과 함께 담아낸다\n4. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 50, 9, 1.4, 'RCP_11754', 0),
(11755, '광주식 콩나물해장국', '두부 1모, 소고기 300g, 당근 1/2개, 연근 200g, 오징어 1마리, 시금치 100g', '1. 소금으로 간을 맞춘다\n2. 약불에서 30분간 푹 끓인다\n3. 팬에 기름을 두르고 센 불에 달군다', 'EXTERNAL_API', 47, 5, 3.1, 'RCP_11755', 0),
(11756, '광주식 북어해장국', '쌈장 2큰술, 부추 100g, 고추 2개, 깻잎 10장, 연근 200g, 당근 1/2개, 다진마늘 1큰술, 마늘 5쪽', '1. 재료를 깨끗이 씻어 준비한다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n4. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 47, 18, 4.8, 'RCP_11756', 0),
(11757, '광주식 황태해장국', '대파 1대, 연근 200g, 맛술 1큰술, 물 500ml, 삼겹살 300g', '1. 양념을 만들어 재료에 버무린다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 밥과 함께 담아낸다\n4. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n5. 뚜껑을 덮고 15분간 끓인다', 'EXTERNAL_API', 18, 16, 3.2, 'RCP_11757', 0),
(11758, '광주식 육개장', '김치 300g, 배즙 3큰술, 대파 1대, 멸치 육수 500ml, 당면 200g, 물 500ml', '1. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n2. 재료를 깨끗이 씻어 준비한다\n3. 소금으로 간을 맞춘다\n4. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 0, 14, 2.8, 'RCP_11758', 0),
(11759, '광주식 닭개장', '물 500ml, 새우 200g, 파프리카 1개, 두부 1모, 맛술 1큰술', '1. 양념장을 넣고 골고루 섞는다\n2. 밥과 함께 담아낸다\n3. 대파를 넣고 한소끔 끓인다\n4. 그릇에 담아 깨소금을 뿌린다\n5. 뚜껑을 덮고 15분간 끓인다', 'EXTERNAL_API', 29, 3, 3.6, 'RCP_11759', 0),
(11760, '광주식 우거지탕', '고춧가루 1큰술, 무 200g, 김치 300g, 양파 1개, 식용유 2큰술, 감자 2개', '1. 재료를 깨끗이 씻어 준비한다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 양념을 만들어 재료에 버무린다\n4. 참기름을 두르고 불을 끈다\n5. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 6, 12, 4.9, 'RCP_11760', 0),
(11761, '광주식 추어탕', '고추 2개, 시금치 100g, 참기름 1큰술, 닭고기 400g, 무 200g, 돼지고기 200g', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 대파를 넣고 한소끔 끓인다\n3. 소금으로 간을 맞춘다', 'EXTERNAL_API', 37, 23, 2.6, 'RCP_11761', 0),
(11762, '광주식 매운탕', '김치 300g, 부추 100g, 호박 1/2개, 당면 200g', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 약불에서 30분간 푹 끓인다\n3. 뚜껑을 덮고 15분간 끓인다\n4. 밥과 함께 담아낸다\n5. 물을 붓고 끓기 시작하면 중불로 줄인다', 'EXTERNAL_API', 27, 30, 1.8, 'RCP_11762', 0),
(11763, '광주식 대구탕', '후추 약간, 새송이버섯 2개, 깻잎 10장, 오징어 1마리, 김치 300g, 파프리카 1개', '1. 냄비에 육수를 넣고 끓인다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 야채를 데쳐서 찬물에 헹군다', 'EXTERNAL_API', 35, 2, 2.9, 'RCP_11763', 0),
