INSERT INTO recipe (id, title, ingredients_raw, instructions_raw, source_type, review_count, wish_count, avg_score, source_ref, version) VALUES
(12101, '대전식 삼겹살구이', '김치 300g, 쌀 2컵, 미역 20g, 된장 2큰술, 소고기 300g, 느타리버섯 100g, 멸치 육수 500ml', '1. 재료를 깨끗이 씻어 준비한다\n2. 야채를 데쳐서 찬물에 헹군다\n3. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 40, 2, 4.7, 'RCP_12101', 0),
(12102, '대전식 소고기구이', '브로콜리 1개, 감자 2개, 표고버섯 4개, 고춧가루 1큰술, 호박 1/2개, 식용유 2큰술, 다진마늘 1큰술', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 참기름을 두르고 불을 끈다\n3. 냄비에 육수를 넣고 끓인다\n4. 뚜껑을 덮고 15분간 끓인다\n5. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 47, 2, 1.3, 'RCP_12102', 0),
(12103, '대전식 닭구이', '맛술 1큰술, 미역 20g, 두부 1모, 어묵 200g', '1. 양념장을 넣고 골고루 섞는다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 팬에 기름을 두르고 센 불에 달군다', 'EXTERNAL_API', 4, 30, 2.6, 'RCP_12103', 0),
(12104, '대전식 고등어구이', '시금치 100g, 식용유 2큰술, 호박 1/2개, 계란 2개', '1. 뚜껑을 덮고 15분간 끓인다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 20, 27, 2.9, 'RCP_12104', 0),
(12105, '대전식 갈치구이', '파프리카 1개, 쌈장 2큰술, 어묵 200g, 맛술 1큰술, 된장 2큰술, 고추장 2큰술, 대파 1대, 밀가루 1컵', '1. 양념장을 넣고 골고루 섞는다\n2. 재료를 깨끗이 씻어 준비한다\n3. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 5, 7, 3.3, 'RCP_12105', 0),
(12106, '대전식 삼치구이', '브로콜리 1개, 오징어 1마리, 물 500ml, 맛술 1큰술, 닭고기 400g, 돼지고기 200g, 버섯 100g, 배즙 3큰술', '1. 재료를 깨끗이 씻어 준비한다\n2. 그릇에 담아 깨소금을 뿌린다\n3. 대파를 넣고 한소끔 끓인다\n4. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 12, 13, 4.8, 'RCP_12106', 0),
(12107, '대전식 연어구이', '고춧가루 1큰술, 멸치 육수 500ml, 양배추 200g, 느타리버섯 100g, 마늘 5쪽', '1. 야채를 데쳐서 찬물에 헹군다\n2. 냄비에 육수를 넣고 끓인다\n3. 접시에 보기 좋게 담아낸다\n4. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 32, 11, 3.0, 'RCP_12107', 0),
(12108, '대전식 새우구이', '고춧가루 1큰술, 굴소스 1큰술, 팽이버섯 100g, 양배추 200g, 닭고기 400g, 참기름 1큰술, 오징어 1마리, 부추 100g', '1. 참기름을 두르고 불을 끈다\n2. 재료를 깨끗이 씻어 준비한다\n3. 접시에 보기 좋게 담아낸다\n4. 양념장을 넣고 골고루 섞는다', 'EXTERNAL_API', 18, 18, 2.7, 'RCP_12108', 0),
(12109, '대전식 오리구이', '물 500ml, 고구마 2개, 식용유 2큰술, 피망 1개, 부추 100g, 연근 200g, 양배추 200g', '1. 참기름을 두르고 불을 끈다\n2. 야채를 적당한 크기로 썰어 준비한다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 접시에 보기 좋게 담아낸다\n5. 밥과 함께 담아낸다', 'EXTERNAL_API', 23, 12, 1.3, 'RCP_12109', 0),
(12110, '대전식 항정살구이', '참기름 1큰술, 깻잎 10장, 굴소스 1큰술, 설탕 1큰술, 깨소금 1작은술, 김치 300g', '1. 뚜껑을 덮고 15분간 끓인다\n2. 그릇에 담아 깨소금을 뿌린다\n3. 양념장을 넣고 골고루 섞는다\n4. 밥과 함께 담아낸다\n5. 소금으로 간을 맞춘다', 'EXTERNAL_API', 35, 4, 3.5, 'RCP_12110', 0),
(12111, '대전식 목살구이', '팽이버섯 100g, 돼지고기 200g, 두부 1모, 굴소스 1큰술, 호박 1/2개, 멸치 육수 500ml, 다진마늘 1큰술, 맛술 1큰술', '1. 양념장을 넣고 골고루 섞는다\n2. 두부를 넣고 5분 더 끓인다\n3. 참기름을 두르고 불을 끈다', 'EXTERNAL_API', 35, 25, 1.9, 'RCP_12111', 0),
(12112, '대전식 가브리살구이', '새송이버섯 2개, 팽이버섯 100g, 고추 2개, 대파 1대, 고추장 2큰술, 배즙 3큰술', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 팬에 기름을 두르고 센 불에 달군다\n4. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n5. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 4, 26, 2.2, 'RCP_12112', 0),
(12113, '대전식 치킨스테이크', '쌀 2컵, 파프리카 1개, 생강 1쪽, 소고기 300g, 맛술 1큰술, 참기름 1큰술', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 뚜껑을 덮고 15분간 끓인다\n4. 야채를 적당한 크기로 썰어 준비한다\n5. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다', 'EXTERNAL_API', 6, 28, 1.1, 'RCP_12113', 0),
(12114, '대전식 돼지갈비구이', '두부 1모, 감자 2개, 미역 20g, 느타리버섯 100g', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 참기름을 두르고 불을 끈다\n4. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n5. 그릇에 담아 깨소금을 뿌린다', 'EXTERNAL_API', 47, 10, 2.3, 'RCP_12114', 0),
(12115, '대전식 소갈비구이', '김치 300g, 고추 2개, 물 500ml, 멸치 육수 500ml, 깻잎 10장, 버섯 100g', '1. 양념을 만들어 재료에 버무린다\n2. 참기름을 두르고 불을 끈다\n3. 고기를 먹기 좋은 크기로 썬다\n4. 재료를 깨끗이 씻어 준비한다\n5. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 20, 23, 3.4, 'RCP_12115', 0),
(12116, '대전식 양념갈비구이', '설탕 1큰술, 맛술 1큰술, 브로콜리 1개, 피망 1개', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 접시에 보기 좋게 담아낸다\n3. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n4. 두부를 넣고 5분 더 끓인다', 'EXTERNAL_API', 44, 29, 4.7, 'RCP_12116', 0),
(12117, '대전식 LA갈비구이', '고추장 2큰술, 김치 300g, 소고기 300g, 된장 2큰술', '1. 뚜껑을 덮고 15분간 끓인다\n2. 양념을 만들어 재료에 버무린다\n3. 두부를 넣고 5분 더 끓인다\n4. 고기를 먹기 좋은 크기로 썬다\n5. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다', 'EXTERNAL_API', 22, 30, 4.9, 'RCP_12117', 0),
(12118, '대전식 돼지등갈비구이', '된장 2큰술, 물 500ml, 버섯 100g, 고춧가루 1큰술', '1. 양념장을 넣고 골고루 섞는다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 밥과 함께 담아낸다\n4. 소금으로 간을 맞춘다\n5. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 13, 6, 2.3, 'RCP_12118', 0),
(12119, '대전식 닭갈비구이', '돼지고기 200g, 감자 2개, 된장 2큰술, 고추 2개, 버섯 100g', '1. 야채를 데쳐서 찬물에 헹군다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 소금으로 간을 맞춘다', 'EXTERNAL_API', 8, 17, 2.7, 'RCP_12119', 0),
(12120, '대전식 매운닭갈비', '마늘 5쪽, 연근 200g, 맛술 1큰술, 오징어 1마리, 깨소금 1작은술, 피망 1개', '1. 소금으로 간을 맞춘다\n2. 대파를 넣고 한소끔 끓인다\n3. 접시에 보기 좋게 담아낸다\n4. 밥과 함께 담아낸다', 'EXTERNAL_API', 22, 30, 5.0, 'RCP_12120', 0),
(12121, '대전식 치즈닭갈비', '부추 100g, 배즙 3큰술, 고춧가루 1큰술, 고추 2개', '1. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n2. 재료를 깨끗이 씻어 준비한다\n3. 참기름을 두르고 불을 끈다', 'EXTERNAL_API', 10, 13, 3.1, 'RCP_12121', 0),
(12122, '대전식 삼겹살김치구이', '어묵 200g, 양파 1개, 고춧가루 1큰술, 피망 1개, 느타리버섯 100g, 밀가루 1컵, 양배추 200g, 떡 300g', '1. 재료를 깨끗이 씻어 준비한다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 31, 1, 3.8, 'RCP_12122', 0),
(12123, '대전식 두부구이', '소고기 300g, 밀가루 1컵, 돼지고기 200g, 된장 2큰술, 후추 약간', '1. 그릇에 담아 깨소금을 뿌린다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 재료를 깨끗이 씻어 준비한다\n4. 야채를 데쳐서 찬물에 헹군다', 'EXTERNAL_API', 36, 2, 3.5, 'RCP_12123', 0),
(12124, '대전식 버섯구이', '식용유 2큰술, 굴소스 1큰술, 고구마 2개, 참기름 1큰술, 오징어 1마리', '1. 재료를 깨끗이 씻어 준비한다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 냄비에 육수를 넣고 끓인다\n4. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n5. 그릇에 담아 깨소금을 뿌린다', 'EXTERNAL_API', 45, 20, 2.3, 'RCP_12124', 0),
(12125, '대전식 가지구이', '떡 300g, 설탕 1큰술, 버섯 100g, 느타리버섯 100g, 물 500ml, 쌈장 2큰술, 쌀 2컵', '1. 뚜껑을 덮고 15분간 끓인다\n2. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n3. 두부를 넣고 5분 더 끓인다\n4. 양념을 만들어 재료에 버무린다\n5. 물을 붓고 끓기 시작하면 중불로 줄인다', 'EXTERNAL_API', 49, 13, 1.1, 'RCP_12125', 0),
(12126, '대전식 호박구이', '설탕 1큰술, 참기름 1큰술, 당면 200g, 떡 300g, 쌈장 2큰술, 깨소금 1작은술, 배즙 3큰술', '1. 양념장을 넣고 골고루 섞는다\n2. 그릇에 담아 깨소금을 뿌린다\n3. 뚜껑을 덮고 15분간 끓인다\n4. 소금으로 간을 맞춘다\n5. 재료를 깨끗이 씻어 준비한다', 'EXTERNAL_API', 40, 19, 3.2, 'RCP_12126', 0),
(12127, '대전식 고구마구이', '쌀 2컵, 어묵 200g, 당근 1/2개, 고구마 2개, 양배추 200g, 대파 1대, 콩나물 200g', '1. 밥과 함께 담아낸다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 소금으로 간을 맞춘다\n4. 재료를 깨끗이 씻어 준비한다\n5. 두부를 넣고 5분 더 끓인다', 'EXTERNAL_API', 49, 4, 3.8, 'RCP_12127', 0),
(12128, '대전식 감자구이', '가지 2개, 시금치 100g, 간장 3큰술, 참기름 1큰술', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 야채를 데쳐서 찬물에 헹군다\n3. 야채를 적당한 크기로 썰어 준비한다', 'EXTERNAL_API', 49, 12, 1.5, 'RCP_12128', 0),
(12129, '대전식 옥수수구이', '가지 2개, 고구마 2개, 양파 1개, 두부 1모, 고춧가루 1큰술, 파프리카 1개, 밀가루 1컵, 맛술 1큰술', '1. 재료를 깨끗이 씻어 준비한다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n4. 양념을 만들어 재료에 버무린다\n5. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 36, 13, 1.6, 'RCP_12129', 0),
(12130, '대전식 파구이', '참기름 1큰술, 대파 1대, 부추 100g, 새송이버섯 2개, 마늘 5쪽, 후추 약간, 밀가루 1컵, 된장 2큰술', '1. 고기를 먹기 좋은 크기로 썬다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 참기름을 두르고 불을 끈다\n4. 물을 붓고 끓기 시작하면 중불로 줄인다\n5. 재료를 깨끗이 씻어 준비한다', 'EXTERNAL_API', 23, 1, 3.6, 'RCP_12130', 0),
(12131, '대전식 대파구이', '마늘 5쪽, 고춧가루 1큰술, 생강 1쪽, 대파 1대, 두부 1모, 김치 300g, 부추 100g', '1. 재료를 깨끗이 씻어 준비한다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 물을 붓고 끓기 시작하면 중불로 줄인다', 'EXTERNAL_API', 23, 20, 1.1, 'RCP_12131', 0),
