INSERT INTO recipe (id, title, ingredients_raw, instructions_raw, source_type, review_count, wish_count, avg_score, source_ref, version) VALUES
(37051, '할머니의 배추김치(저칼로리)', '대파 1대, 새우 200g, 계란 2개, 쌀 2컵, 고추장 2큰술', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 뚜껑을 덮고 15분간 끓인다\n3. 그릇에 담아 깨소금을 뿌린다\n4. 양념을 만들어 재료에 버무린다\n5. 물을 붓고 끓기 시작하면 중불로 줄인다', 'EXTERNAL_API', 1, 27, 3.0, 'RCP_37051', 0),
(37052, '할머니의 총각김치(저칼로리)', '가지 2개, 설탕 1큰술, 간장 3큰술, 파프리카 1개', '1. 대파를 넣고 한소끔 끓인다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 재료를 깨끗이 씻어 준비한다\n4. 고기를 먹기 좋은 크기로 썬다\n5. 그릇에 담아 깨소금을 뿌린다', 'EXTERNAL_API', 20, 1, 2.0, 'RCP_37052', 0),
(37053, '할머니의 갓김치(저칼로리)', '김치 300g, 소고기 300g, 부추 100g, 호박 1/2개, 쌀 2컵', '1. 고기를 먹기 좋은 크기로 썬다\n2. 냄비에 육수를 넣고 끓인다\n3. 물을 붓고 끓기 시작하면 중불로 줄인다\n4. 양념장을 넣고 골고루 섞는다', 'EXTERNAL_API', 25, 30, 1.5, 'RCP_37053', 0),
(37054, '할머니의 부추김치(저칼로리)', '깨소금 1작은술, 양파 1개, 팽이버섯 100g, 간장 3큰술, 고춧가루 1큰술, 굴소스 1큰술, 대파 1대', '1. 재료를 깨끗이 씻어 준비한다\n2. 대파를 넣고 한소끔 끓인다\n3. 약불에서 30분간 푹 끓인다\n4. 고기를 먹기 좋은 크기로 썬다\n5. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 24, 15, 4.5, 'RCP_37054', 0),
(37055, '할머니의 파김치(저칼로리)', '후추 약간, 호박 1/2개, 계란 2개, 생강 1쪽, 느타리버섯 100g, 깻잎 10장', '1. 두부를 넣고 5분 더 끓인다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 밥과 함께 담아낸다\n4. 뚜껑을 덮고 15분간 끓인다', 'EXTERNAL_API', 31, 10, 1.7, 'RCP_37055', 0),
(37056, '할머니의 열무김치(저칼로리)', '두부 1모, 김치 300g, 깻잎 10장, 설탕 1큰술, 소금 약간, 물 500ml, 호박 1/2개', '1. 대파를 넣고 한소끔 끓인다\n2. 야채를 데쳐서 찬물에 헹군다\n3. 양념을 만들어 재료에 버무린다', 'EXTERNAL_API', 15, 9, 2.3, 'RCP_37056', 0),
(37057, '할머니의 동치미(저칼로리)', '소고기 300g, 오징어 1마리, 다진마늘 1큰술, 배추 300g, 설탕 1큰술, 연근 200g, 후추 약간, 콩나물 200g', '1. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n2. 소금으로 간을 맞춘다\n3. 물을 붓고 끓기 시작하면 중불로 줄인다', 'EXTERNAL_API', 29, 13, 2.2, 'RCP_37057', 0),
(37058, '할머니의 백김치(저칼로리)', '느타리버섯 100g, 된장 2큰술, 브로콜리 1개, 물 500ml, 다진마늘 1큰술', '1. 양념장을 넣고 골고루 섞는다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 소금으로 간을 맞춘다\n4. 접시에 보기 좋게 담아낸다\n5. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 22, 4, 1.8, 'RCP_37058', 0),
(37059, '할머니의 시금치나물(저칼로리)', '감자 2개, 고춧가루 1큰술, 당면 200g, 어묵 200g, 간장 3큰술, 생강 1쪽, 양파 1개, 고추 2개', '1. 야채를 데쳐서 찬물에 헹군다\n2. 양념장을 넣고 골고루 섞는다\n3. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n4. 참기름을 두르고 불을 끈다\n5. 그릇에 담아 깨소금을 뿌린다', 'EXTERNAL_API', 27, 17, 1.0, 'RCP_37059', 0),
(37060, '할머니의 콩나물무침(저칼로리)', '김치 300g, 마늘 5쪽, 돼지고기 200g, 쌈장 2큰술, 고구마 2개, 고추 2개, 계란 2개, 배즙 3큰술', '1. 고기를 먹기 좋은 크기로 썬다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 소금으로 간을 맞춘다\n4. 물을 붓고 끓기 시작하면 중불로 줄인다', 'EXTERNAL_API', 19, 10, 1.8, 'RCP_37060', 0),
(37061, '할머니의 숙주나물(저칼로리)', '밀가루 1컵, 당근 1/2개, 떡 300g, 부추 100g', '1. 양념장을 넣고 골고루 섞는다\n2. 재료를 깨끗이 씻어 준비한다\n3. 팬에 기름을 두르고 센 불에 달군다', 'EXTERNAL_API', 26, 30, 3.0, 'RCP_37061', 0),
(37062, '할머니의 고사리나물(저칼로리)', '감자 2개, 양파 1개, 버섯 100g, 간장 3큰술, 부추 100g', '1. 접시에 보기 좋게 담아낸다\n2. 재료를 깨끗이 씻어 준비한다\n3. 밥과 함께 담아낸다', 'EXTERNAL_API', 27, 24, 1.3, 'RCP_37062', 0),
(37063, '할머니의 도라지나물(저칼로리)', '깨소금 1작은술, 대파 1대, 후추 약간, 맛술 1큰술, 당면 200g, 브로콜리 1개, 고구마 2개', '1. 참기름을 두르고 불을 끈다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 물을 붓고 끓기 시작하면 중불로 줄인다\n4. 야채를 데쳐서 찬물에 헹군다', 'EXTERNAL_API', 25, 2, 3.5, 'RCP_37063', 0),
