INSERT INTO recipe (id, title, ingredients_raw, instructions_raw, source_type, review_count, wish_count, avg_score, source_ref, version) VALUES
(40051, '할머니의 제육볶음 한정판', '깻잎 10장, 다진마늘 1큰술, 당근 1/2개, 참기름 1큰술, 물 500ml, 맛술 1큰술, 마늘 5쪽', '1. 고기를 먹기 좋은 크기로 썬다\n2. 밥과 함께 담아낸다\n3. 팬에 기름을 두르고 센 불에 달군다', 'EXTERNAL_API', 20, 17, 3.6, 'RCP_40051', 0),
(40052, '할머니의 오징어볶음 한정판', '시금치 100g, 감자 2개, 참기름 1큰술, 후추 약간, 두부 1모', '1. 양념을 만들어 재료에 버무린다\n2. 야채를 적당한 크기로 썰어 준비한다\n3. 그릇에 담아 깨소금을 뿌린다\n4. 물을 붓고 끓기 시작하면 중불로 줄인다', 'EXTERNAL_API', 32, 13, 3.4, 'RCP_40052', 0),
(40053, '할머니의 낙지볶음 한정판', '부추 100g, 쌀 2컵, 표고버섯 4개, 미역 20g, 간장 3큰술', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 냄비에 육수를 넣고 끓인다\n3. 고기를 먹기 좋은 크기로 썬다\n4. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 47, 5, 4.0, 'RCP_40053', 0),
(40054, '할머니의 쭈꾸미볶음 한정판', '김치 300g, 당근 1/2개, 새송이버섯 2개, 깻잎 10장, 양파 1개, 계란 2개, 연근 200g, 돼지고기 200g', '1. 냄비에 육수를 넣고 끓인다\n2. 뚜껑을 덮고 15분간 끓인다\n3. 팬에 기름을 두르고 센 불에 달군다\n4. 약불에서 30분간 푹 끓인다\n5. 야채를 적당한 크기로 썰어 준비한다', 'EXTERNAL_API', 44, 1, 1.6, 'RCP_40054', 0),
(40055, '할머니의 김치볶음 한정판', '돼지고기 200g, 가지 2개, 깨소금 1작은술, 김치 300g, 소고기 300g, 참기름 1큰술, 오징어 1마리', '1. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n2. 그릇에 담아 깨소금을 뿌린다\n3. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다', 'EXTERNAL_API', 13, 22, 1.2, 'RCP_40055', 0),
(40056, '할머니의 멸치볶음 한정판', '식용유 2큰술, 무 200g, 김치 300g, 콩나물 200g, 당근 1/2개', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 양념장을 넣고 골고루 섞는다\n3. 접시에 보기 좋게 담아낸다\n4. 약불에서 30분간 푹 끓인다\n5. 대파를 넣고 한소끔 끓인다', 'EXTERNAL_API', 11, 8, 2.2, 'RCP_40056', 0),
(40057, '할머니의 어묵볶음 한정판', '굴소스 1큰술, 다진마늘 1큰술, 당근 1/2개, 깻잎 10장, 오징어 1마리, 떡 300g', '1. 소금으로 간을 맞춘다\n2. 대파를 넣고 한소끔 끓인다\n3. 밥과 함께 담아낸다\n4. 팬에 기름을 두르고 센 불에 달군다\n5. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 28, 29, 2.1, 'RCP_40057', 0),
(40058, '할머니의 감자볶음 한정판', '물 500ml, 다진마늘 1큰술, 소고기 300g, 고추 2개, 새송이버섯 2개', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 팬에 기름을 두르고 센 불에 달군다\n5. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다', 'EXTERNAL_API', 42, 9, 2.1, 'RCP_40058', 0),
(40059, '할머니의 버섯볶음 한정판', '연근 200g, 된장 2큰술, 후추 약간, 계란 2개', '1. 재료를 깨끗이 씻어 준비한다\n2. 대파를 넣고 한소끔 끓인다\n3. 고기를 먹기 좋은 크기로 썬다\n4. 야채를 데쳐서 찬물에 헹군다', 'EXTERNAL_API', 9, 9, 3.5, 'RCP_40059', 0),
(40060, '할머니의 소시지볶음 한정판', '간장 3큰술, 물 500ml, 설탕 1큰술, 오징어 1마리, 새우 200g, 고춧가루 1큰술, 파프리카 1개, 맛술 1큰술', '1. 야채를 데쳐서 찬물에 헹군다\n2. 재료를 깨끗이 씻어 준비한다\n3. 밥과 함께 담아낸다\n4. 고기를 먹기 좋은 크기로 썬다\n5. 두부를 넣고 5분 더 끓인다', 'EXTERNAL_API', 37, 11, 4.3, 'RCP_40060', 0),
(40061, '할머니의 두부볶음 한정판', '참기름 1큰술, 배추 300g, 당근 1/2개, 브로콜리 1개, 후추 약간, 마늘 5쪽, 호박 1/2개', '1. 양념장을 넣고 골고루 섞는다\n2. 재료를 깨끗이 씻어 준비한다\n3. 접시에 보기 좋게 담아낸다\n4. 양파와 마늘을 넣고 향이 날 때까지 볶는다', 'EXTERNAL_API', 43, 15, 3.6, 'RCP_40061', 0),
(40062, '할머니의 고추장볶음 한정판', '깻잎 10장, 고춧가루 1큰술, 새우 200g, 후추 약간, 느타리버섯 100g, 멸치 육수 500ml, 새송이버섯 2개, 소고기 300g', '1. 밥과 함께 담아낸다\n2. 소금으로 간을 맞춘다\n3. 물을 붓고 끓기 시작하면 중불로 줄인다\n4. 팬에 기름을 두르고 센 불에 달군다\n5. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 18, 23, 4.7, 'RCP_40062', 0),
(40063, '할머니의 된장볶음 한정판', '배추 300g, 쌀 2컵, 미역 20g, 김치 300g, 당근 1/2개, 고추 2개, 파프리카 1개', '1. 재료를 깨끗이 씻어 준비한다\n2. 야채를 데쳐서 찬물에 헹군다\n3. 양념장을 넣고 골고루 섞는다\n4. 물을 붓고 끓기 시작하면 중불로 줄인다\n5. 대파를 넣고 한소끔 끓인다', 'EXTERNAL_API', 22, 3, 2.8, 'RCP_40063', 0),
(40064, '할머니의 마늘쫑볶음 한정판', '돼지고기 200g, 깨소금 1작은술, 새송이버섯 2개, 깻잎 10장, 호박 1/2개', '1. 약불에서 30분간 푹 끓인다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 야채를 적당한 크기로 썰어 준비한다\n4. 소금으로 간을 맞춘다\n5. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 8, 27, 2.9, 'RCP_40064', 0),
(40065, '할머니의 피망볶음 한정판', '고추 2개, 식용유 2큰술, 고춧가루 1큰술, 맛술 1큰술, 물 500ml, 양파 1개', '1. 양념을 만들어 재료에 버무린다\n2. 냄비에 육수를 넣고 끓인다\n3. 팬에 기름을 두르고 센 불에 달군다', 'EXTERNAL_API', 38, 15, 4.6, 'RCP_40065', 0),
(40066, '할머니의 새우볶음 한정판', '식용유 2큰술, 대파 1대, 무 200g, 삼겹살 300g, 연근 200g, 멸치 육수 500ml, 두부 1모, 고구마 2개', '1. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n2. 냄비에 육수를 넣고 끓인다\n3. 약불에서 30분간 푹 끓인다\n4. 양념장을 넣고 골고루 섞는다\n5. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 0, 16, 1.6, 'RCP_40066', 0),
(40067, '할머니의 해물볶음 한정판', '간장 3큰술, 새우 200g, 밀가루 1컵, 대파 1대, 두부 1모, 당근 1/2개, 당면 200g, 배즙 3큰술', '1. 물을 붓고 끓기 시작하면 중불로 줄인다\n2. 밥과 함께 담아낸다\n3. 약불에서 30분간 푹 끓인다\n4. 야채를 적당한 크기로 썰어 준비한다\n5. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 39, 9, 2.4, 'RCP_40067', 0),
(40068, '할머니의 닭볶음 한정판', '새우 200g, 돼지고기 200g, 계란 2개, 피망 1개, 쌀 2컵, 다진마늘 1큰술, 두부 1모, 고추장 2큰술', '1. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n2. 두부를 넣고 5분 더 끓인다\n3. 밥과 함께 담아낸다\n4. 야채를 적당한 크기로 썰어 준비한다', 'EXTERNAL_API', 7, 9, 1.2, 'RCP_40068', 0),
(40069, '할머니의 돼지볶음 한정판', '연근 200g, 맛술 1큰술, 배즙 3큰술, 돼지고기 200g', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 대파를 넣고 한소끔 끓인다\n3. 재료를 깨끗이 씻어 준비한다\n4. 약불에서 30분간 푹 끓인다\n5. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 22, 19, 1.4, 'RCP_40069', 0),
(40070, '할머니의 소고기볶음 한정판', '배즙 3큰술, 시금치 100g, 버섯 100g, 고춧가루 1큰술, 생강 1쪽, 참기름 1큰술, 배추 300g, 미역 20g', '1. 재료를 깨끗이 씻어 준비한다\n2. 대파를 넣고 한소끔 끓인다\n3. 팬에 기름을 두르고 센 불에 달군다\n4. 그릇에 담아 깨소금을 뿌린다\n5. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 27, 3, 2.9, 'RCP_40070', 0),
(40071, '할머니의 양배추볶음 한정판', '소금 약간, 굴소스 1큰술, 감자 2개, 소고기 300g, 양배추 200g', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 소금으로 간을 맞춘다\n4. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 41, 15, 1.1, 'RCP_40071', 0),
(40072, '할머니의 콩나물볶음 한정판', '대파 1대, 당근 1/2개, 고추 2개, 소금 약간', '1. 그릇에 담아 깨소금을 뿌린다\n2. 참기름을 두르고 불을 끈다\n3. 양념을 만들어 재료에 버무린다\n4. 약불에서 30분간 푹 끓인다', 'EXTERNAL_API', 14, 18, 3.0, 'RCP_40072', 0),
(40073, '할머니의 시금치볶음 한정판', '간장 3큰술, 대파 1대, 미역 20g, 고추 2개, 두부 1모, 다진마늘 1큰술', '1. 대파를 넣고 한소끔 끓인다\n2. 재료를 깨끗이 씻어 준비한다\n3. 팬에 기름을 두르고 센 불에 달군다\n4. 약불에서 30분간 푹 끓인다\n5. 두부를 넣고 5분 더 끓인다', 'EXTERNAL_API', 23, 27, 1.5, 'RCP_40073', 0),
(40074, '할머니의 가지볶음 한정판', '고춧가루 1큰술, 김치 300g, 참기름 1큰술, 맛술 1큰술, 시금치 100g', '1. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n2. 두부를 넣고 5분 더 끓인다\n3. 그릇에 담아 깨소금을 뿌린다', 'EXTERNAL_API', 3, 17, 1.1, 'RCP_40074', 0),
(40075, '할머니의 호박볶음 한정판', '시금치 100g, 된장 2큰술, 물 500ml, 배추 300g, 피망 1개, 대파 1대', '1. 양념장을 넣고 골고루 섞는다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 참기름을 두르고 불을 끈다', 'EXTERNAL_API', 24, 14, 1.7, 'RCP_40075', 0),
(40076, '할머니의 브로콜리볶음 한정판', '물 500ml, 쌀 2컵, 버섯 100g, 배즙 3큰술, 감자 2개, 삼겹살 300g', '1. 양념을 만들어 재료에 버무린다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 재료를 깨끗이 씻어 준비한다', 'EXTERNAL_API', 39, 22, 1.9, 'RCP_40076', 0),
(40077, '할머니의 당근볶음 한정판', '고추장 2큰술, 버섯 100g, 어묵 200g, 식용유 2큰술, 쌀 2컵, 당면 200g', '1. 참기름을 두르고 불을 끈다\n2. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n3. 고기를 먹기 좋은 크기로 썬다\n4. 양념을 만들어 재료에 버무린다', 'EXTERNAL_API', 11, 26, 1.0, 'RCP_40077', 0),
(40078, '할머니의 파프리카볶음 한정판', '감자 2개, 피망 1개, 소고기 300g, 새송이버섯 2개, 콩나물 200g, 새우 200g', '1. 대파를 넣고 한소끔 끓인다\n2. 두부를 넣고 5분 더 끓인다\n3. 약불에서 30분간 푹 끓인다\n4. 참기름을 두르고 불을 끈다\n5. 물을 붓고 끓기 시작하면 중불로 줄인다', 'EXTERNAL_API', 21, 29, 3.9, 'RCP_40078', 0),
(40079, '할머니의 고구마볶음 한정판', '김치 300g, 설탕 1큰술, 돼지고기 200g, 후추 약간, 깻잎 10장, 느타리버섯 100g', '1. 접시에 보기 좋게 담아낸다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 양념장을 넣고 골고루 섞는다\n4. 약불에서 30분간 푹 끓인다\n5. 밥과 함께 담아낸다', 'EXTERNAL_API', 16, 6, 4.5, 'RCP_40079', 0),
(40080, '할머니의 애호박볶음 한정판', '미역 20g, 돼지고기 200g, 새우 200g, 감자 2개', '1. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 야채를 적당한 크기로 썰어 준비한다', 'EXTERNAL_API', 29, 10, 2.9, 'RCP_40080', 0),
(40081, '할머니의 김치삼겹살볶음 한정판', '맛술 1큰술, 다진마늘 1큰술, 설탕 1큰술, 무 200g, 어묵 200g, 미역 20g, 삼겹살 300g', '1. 뚜껑을 덮고 15분간 끓인다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 양념장을 넣고 골고루 섞는다\n4. 야채를 데쳐서 찬물에 헹군다\n5. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다', 'EXTERNAL_API', 6, 20, 5.0, 'RCP_40081', 0),
(40082, '할머니의 돼지고기두부볶음 한정판', '생강 1쪽, 팽이버섯 100g, 쌈장 2큰술, 고추 2개, 새우 200g, 당근 1/2개, 양파 1개, 표고버섯 4개', '1. 약불에서 30분간 푹 끓인다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 41, 9, 4.4, 'RCP_40082', 0),
(40083, '할머니의 닭가슴살볶음 한정판', '닭고기 400g, 오징어 1마리, 연근 200g, 고추 2개, 두부 1모, 팽이버섯 100g, 식용유 2큰술', '1. 밥과 함께 담아낸다\n2. 소금으로 간을 맞춘다\n3. 고기를 먹기 좋은 크기로 썬다\n4. 물을 붓고 끓기 시작하면 중불로 줄인다', 'EXTERNAL_API', 44, 19, 3.6, 'RCP_40083', 0),
(40084, '할머니의 소세지야채볶음 한정판', '양파 1개, 식용유 2큰술, 배즙 3큰술, 무 200g, 생강 1쪽', '1. 약불에서 30분간 푹 끓인다\n2. 물을 붓고 끓기 시작하면 중불로 줄인다\n3. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n4. 두부를 넣고 5분 더 끓인다\n5. 야채를 적당한 크기로 썰어 준비한다', 'EXTERNAL_API', 13, 11, 4.5, 'RCP_40084', 0),
(40085, '할머니의 매운돼지볶음 한정판', '소고기 300g, 대파 1대, 표고버섯 4개, 연근 200g, 계란 2개, 삼겹살 300g, 깻잎 10장', '1. 참기름을 두르고 불을 끈다\n2. 소금으로 간을 맞춘다\n3. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 49, 16, 3.1, 'RCP_40085', 0),
(40086, '할머니의 간장새우볶음 한정판', '브로콜리 1개, 돼지고기 200g, 느타리버섯 100g, 감자 2개, 깨소금 1작은술, 설탕 1큰술', '1. 두부를 넣고 5분 더 끓인다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 재료를 깨끗이 씻어 준비한다\n4. 양념을 만들어 재료에 버무린다\n5. 양파와 마늘을 넣고 향이 날 때까지 볶는다', 'EXTERNAL_API', 44, 29, 1.5, 'RCP_40086', 0),
(40087, '할머니의 고추장삼겹살볶음 한정판', '시금치 100g, 새우 200g, 연근 200g, 고추 2개, 피망 1개, 김치 300g', '1. 소금으로 간을 맞춘다\n2. 대파를 넣고 한소끔 끓인다\n3. 그릇에 담아 깨소금을 뿌린다', 'EXTERNAL_API', 12, 11, 2.9, 'RCP_40087', 0),
(40088, '할머니의 매운오징어볶음 한정판', '깨소금 1작은술, 버섯 100g, 맛술 1큰술, 김치 300g', '1. 접시에 보기 좋게 담아낸다\n2. 밥과 함께 담아낸다\n3. 대파를 넣고 한소끔 끓인다', 'EXTERNAL_API', 38, 1, 1.9, 'RCP_40088', 0),
(40089, '할머니의 불닭볶음 한정판', '호박 1/2개, 후추 약간, 감자 2개, 생강 1쪽, 멸치 육수 500ml, 간장 3큰술', '1. 야채를 데쳐서 찬물에 헹군다\n2. 그릇에 담아 깨소금을 뿌린다\n3. 밥과 함께 담아낸다\n4. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n5. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 17, 26, 1.6, 'RCP_40089', 0),
(40090, '할머니의 고추잡채볶음 한정판', '새우 200g, 고춧가루 1큰술, 새송이버섯 2개, 소고기 300g, 호박 1/2개, 당근 1/2개', '1. 약불에서 30분간 푹 끓인다\n2. 재료를 깨끗이 씻어 준비한다\n3. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다', 'EXTERNAL_API', 22, 22, 4.8, 'RCP_40090', 0),
(40091, '할머니의 떡볶이 한정판', '돼지고기 200g, 소고기 300g, 감자 2개, 양배추 200g', '1. 그릇에 담아 깨소금을 뿌린다\n2. 밥과 함께 담아낸다\n3. 양념을 만들어 재료에 버무린다', 'EXTERNAL_API', 47, 23, 4.7, 'RCP_40091', 0),
(40092, '할머니의 라볶이 한정판', '무 200g, 설탕 1큰술, 양파 1개, 쌈장 2큰술', '1. 뚜껑을 덮고 15분간 끓인다\n2. 야채를 적당한 크기로 썰어 준비한다\n3. 그릇에 담아 깨소금을 뿌린다\n4. 약불에서 30분간 푹 끓인다\n5. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 8, 1, 1.1, 'RCP_40092', 0),
(40093, '할머니의 치즈떡볶이 한정판', '삼겹살 300g, 새우 200g, 양파 1개, 된장 2큰술, 연근 200g, 떡 300g, 대파 1대', '1. 뚜껑을 덮고 15분간 끓인다\n2. 양념을 만들어 재료에 버무린다\n3. 야채를 적당한 크기로 썰어 준비한다\n4. 약불에서 30분간 푹 끓인다\n5. 소금으로 간을 맞춘다', 'EXTERNAL_API', 24, 29, 4.6, 'RCP_40093', 0),
(40094, '할머니의 궁중떡볶이 한정판', '오징어 1마리, 계란 2개, 부추 100g, 어묵 200g, 김치 300g, 쌈장 2큰술, 굴소스 1큰술', '1. 대파를 넣고 한소끔 끓인다\n2. 재료를 깨끗이 씻어 준비한다\n3. 두부를 넣고 5분 더 끓인다\n4. 고기를 먹기 좋은 크기로 썬다\n5. 양념장을 넣고 골고루 섞는다', 'EXTERNAL_API', 19, 11, 3.4, 'RCP_40094', 0),
(40095, '할머니의 로제떡볶이 한정판', '연근 200g, 다진마늘 1큰술, 후추 약간, 양파 1개, 맛술 1큰술', '1. 그릇에 담아 깨소금을 뿌린다\n2. 야채를 적당한 크기로 썰어 준비한다\n3. 고기를 먹기 좋은 크기로 썬다\n4. 뚜껑을 덮고 15분간 끓인다', 'EXTERNAL_API', 26, 16, 4.7, 'RCP_40095', 0),
(40096, '할머니의 짜장떡볶이 한정판', '깨소금 1작은술, 참기름 1큰술, 삼겹살 300g, 닭고기 400g', '1. 양념장을 넣고 골고루 섞는다\n2. 재료를 깨끗이 씻어 준비한다\n3. 접시에 보기 좋게 담아낸다\n4. 팬에 기름을 두르고 센 불에 달군다', 'EXTERNAL_API', 21, 21, 2.4, 'RCP_40096', 0),
(40097, '할머니의 카레떡볶이 한정판', '맛술 1큰술, 삼겹살 300g, 깻잎 10장, 양파 1개, 된장 2큰술, 고구마 2개', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 재료를 깨끗이 씻어 준비한다\n3. 양념장을 넣고 골고루 섞는다', 'EXTERNAL_API', 5, 6, 1.3, 'RCP_40097', 0),
(40098, '할머니의 해물떡볶이 한정판', '다진마늘 1큰술, 쌈장 2큰술, 파프리카 1개, 오징어 1마리', '1. 접시에 보기 좋게 담아낸다\n2. 두부를 넣고 5분 더 끓인다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 소금으로 간을 맞춘다', 'EXTERNAL_API', 10, 22, 2.3, 'RCP_40098', 0),
(40099, '할머니의 소떡소떡 한정판', '맛술 1큰술, 가지 2개, 깻잎 10장, 당근 1/2개, 굴소스 1큰술, 다진마늘 1큰술, 호박 1/2개, 설탕 1큰술', '1. 뚜껑을 덮고 15분간 끓인다\n2. 두부를 넣고 5분 더 끓인다\n3. 양념을 만들어 재료에 버무린다\n4. 접시에 보기 좋게 담아낸다', 'EXTERNAL_API', 20, 5, 2.1, 'RCP_40099', 0),
(40100, '할머니의 어묵꼬치볶음 한정판', '새우 200g, 닭고기 400g, 호박 1/2개, 배즙 3큰술, 시금치 100g, 굴소스 1큰술, 연근 200g, 느타리버섯 100g', '1. 양념을 만들어 재료에 버무린다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 두부를 넣고 5분 더 끓인다\n4. 소금으로 간을 맞춘다\n5. 재료를 깨끗이 씻어 준비한다', 'EXTERNAL_API', 2, 15, 2.2, 'RCP_40100', 0);
