INSERT INTO recipe (id, title, ingredients_raw, instructions_raw, source_type, review_count, wish_count, avg_score, source_ref, version) VALUES
(48001, '우리집 김치찌개 한정판', '팽이버섯 100g, 연근 200g, 피망 1개, 굴소스 1큰술', '1. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 야채를 적당한 크기로 썰어 준비한다\n4. 두부를 넣고 5분 더 끓인다', 'EXTERNAL_API', 25, 16, 3.5, 'RCP_48001', 0),
(48002, '우리집 된장찌개 한정판', '물 500ml, 돼지고기 200g, 계란 2개, 간장 3큰술', '1. 참기름을 두르고 불을 끈다\n2. 양념을 만들어 재료에 버무린다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 접시에 보기 좋게 담아낸다\n5. 두부를 넣고 5분 더 끓인다', 'EXTERNAL_API', 8, 9, 2.8, 'RCP_48002', 0),
(48003, '우리집 순두부찌개 한정판', '돼지고기 200g, 양파 1개, 두부 1모, 깨소금 1작은술, 대파 1대, 고구마 2개, 팽이버섯 100g, 새송이버섯 2개', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 양념장을 넣고 골고루 섞는다\n3. 야채를 적당한 크기로 썰어 준비한다\n4. 물을 붓고 끓기 시작하면 중불로 줄인다', 'EXTERNAL_API', 40, 20, 2.9, 'RCP_48003', 0),
(48004, '우리집 부대찌개 한정판', '떡 300g, 마늘 5쪽, 부추 100g, 고추 2개', '1. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 양념을 만들어 재료에 버무린다\n5. 야채를 적당한 크기로 썰어 준비한다', 'EXTERNAL_API', 9, 17, 4.9, 'RCP_48004', 0),
(48005, '우리집 청국장찌개 한정판', '감자 2개, 양파 1개, 표고버섯 4개, 새우 200g, 호박 1/2개, 배즙 3큰술, 어묵 200g, 맛술 1큰술', '1. 양념장을 넣고 골고루 섞는다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 밥과 함께 담아낸다\n4. 소금으로 간을 맞춘다\n5. 양파와 마늘을 넣고 향이 날 때까지 볶는다', 'EXTERNAL_API', 46, 22, 4.1, 'RCP_48005', 0),
(48006, '우리집 동태찌개 한정판', '식용유 2큰술, 어묵 200g, 당근 1/2개, 파프리카 1개', '1. 그릇에 담아 깨소금을 뿌린다\n2. 대파를 넣고 한소끔 끓인다\n3. 소금으로 간을 맞춘다', 'EXTERNAL_API', 27, 15, 1.3, 'RCP_48006', 0),
(48007, '우리집 참치김치찌개 한정판', '어묵 200g, 오징어 1마리, 파프리카 1개, 떡 300g, 감자 2개, 깻잎 10장, 대파 1대, 호박 1/2개', '1. 밥과 함께 담아낸다\n2. 두부를 넣고 5분 더 끓인다\n3. 야채를 데쳐서 찬물에 헹군다\n4. 재료를 깨끗이 씻어 준비한다', 'EXTERNAL_API', 29, 3, 4.4, 'RCP_48007', 0),
(48008, '우리집 꽁치김치찌개 한정판', '무 200g, 맛술 1큰술, 쌀 2컵, 간장 3큰술, 돼지고기 200g', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 소금으로 간을 맞춘다\n3. 약불에서 30분간 푹 끓인다\n4. 양념을 만들어 재료에 버무린다\n5. 고기를 먼저 넣고 겉면이 익을 때까지 볶는다', 'EXTERNAL_API', 45, 0, 4.6, 'RCP_48008', 0),
(48009, '우리집 햄김치찌개 한정판', '시금치 100g, 김치 300g, 어묵 200g, 고구마 2개, 새우 200g, 설탕 1큰술', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n3. 대파를 넣고 한소끔 끓인다', 'EXTERNAL_API', 16, 22, 4.3, 'RCP_48009', 0),
(48010, '우리집 소고기된장찌개 한정판', '쌀 2컵, 양파 1개, 연근 200g, 무 200g, 새송이버섯 2개, 감자 2개, 느타리버섯 100g', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 소금으로 간을 맞춘다\n3. 재료를 깨끗이 씻어 준비한다\n4. 고기를 먹기 좋은 크기로 썬다\n5. 두부를 넣고 5분 더 끓인다', 'EXTERNAL_API', 0, 3, 2.9, 'RCP_48010', 0),
(48011, '우리집 버섯된장찌개 한정판', '고구마 2개, 당면 200g, 설탕 1큰술, 다진마늘 1큰술, 생강 1쪽, 삼겹살 300g, 계란 2개, 소금 약간', '1. 대파를 넣고 한소끔 끓인다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 두부를 넣고 5분 더 끓인다\n4. 재료를 깨끗이 씻어 준비한다\n5. 고기를 먹기 좋은 크기로 썬다', 'EXTERNAL_API', 5, 25, 3.5, 'RCP_48011', 0),
(48012, '우리집 조개된장찌개 한정판', '식용유 2큰술, 삼겹살 300g, 김치 300g, 설탕 1큰술', '1. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n2. 고기를 먹기 좋은 크기로 썬다\n3. 참기름을 두르고 불을 끈다', 'EXTERNAL_API', 47, 19, 1.5, 'RCP_48012', 0),
(48013, '우리집 낙지찌개 한정판', '배추 300g, 미역 20g, 삼겹살 300g, 무 200g', '1. 팬에 기름을 두르고 센 불에 달군다\n2. 참기름을 두르고 불을 끈다\n3. 냄비에 육수를 넣고 끓인다\n4. 약불에서 30분간 푹 끓인다\n5. 재료를 깨끗이 씻어 준비한다', 'EXTERNAL_API', 16, 26, 1.8, 'RCP_48013', 0),
(48014, '우리집 감자찌개 한정판', '김치 300g, 미역 20g, 삼겹살 300g, 팽이버섯 100g', '1. 그릇에 담아 깨소금을 뿌린다\n2. 팬에 기름을 두르고 센 불에 달군다\n3. 고기를 먹기 좋은 크기로 썬다\n4. 약불에서 30분간 푹 끓인다\n5. 냄비에 육수를 넣고 끓인다', 'EXTERNAL_API', 29, 30, 4.2, 'RCP_48014', 0),
(48015, '우리집 두부찌개 한정판', '배추 300g, 닭고기 400g, 설탕 1큰술, 고추 2개, 다진마늘 1큰술, 소금 약간, 무 200g, 떡 300g', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 대파를 넣고 한소끔 끓인다\n3. 접시에 보기 좋게 담아낸다\n4. 두부를 넣고 5분 더 끓인다', 'EXTERNAL_API', 37, 13, 4.2, 'RCP_48015', 0),
(48016, '우리집 열무된장찌개 한정판', '당근 1/2개, 돼지고기 200g, 양파 1개, 고추 2개, 대파 1대, 다진마늘 1큰술, 깨소금 1작은술', '1. 야채를 적당한 크기로 썰어 준비한다\n2. 뚜껑을 덮고 15분간 끓인다\n3. 양파와 마늘을 넣고 향이 날 때까지 볶는다\n4. 양념을 만들어 재료에 버무린다\n5. 참기름을 두르고 불을 끈다', 'EXTERNAL_API', 34, 26, 3.9, 'RCP_48016', 0),
